import subprocess
import unittest
import os.path
import tempfile
from unittest import mock

class BashFunctionCaller(object):

    def __init__(self, script):
        self.script = script

    def __getattr__(self, name):
        def call_fun(*args):
            script_path = "'{}'".format(os.path.join(os.path.dirname(__file__), self.script))
            return subprocess.check_output(
                    ['bash', '-c', 'source {} && {} {}'.format(script_path, name, " ".join(args))],
                    universal_newlines=True)

        return call_fun



class TestSetupGpgKey(unittest.TestCase):

    def setUp(self):
        self.script = BashFunctionCaller("../../setup_gpg.sh")


    @mock.patch.dict(os.environ, {
        "HOME": os.environ.get("HOME"),
        "GITHUB_API_TOKEN": "dummy_token",
        "GITHUB_API_USER": "user.name",
        "GITHUB_API_EMAIL": "user@email.com",
        "GPG_PRIVATE_KEY_1": "",
        "GPG_PRIVATE_KEY_2": "",
        "GPG_PRIVATE_KEY_3": ""
        }, clear=True)
    def test_success(self) -> None:
        with tempfile.TemporaryDirectory() as directory:
            output = self.script.main(directory)
            self.assertEqual("", output)

    @mock.patch.dict(os.environ, {}, clear=True)
    def test_no_env_vars(self):
        with tempfile.TemporaryDirectory() as directory:
            with self.assertRaises(Exception):
                self.script.main()
